def count_coprime_pairs(x0: int, y0: int) -> int:
    # If y0 is not a multiple of x0, no such pairs exist
    if y0 % x0 != 0:
        return 0

    n = y0 // x0

    # Helper function to compute gcd
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(n ** 0.5)
    for a in range(1, limit + 1):
        if n % a == 0:
            b = n // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

