def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Ensure we only consider the first n items
    items = volumes[:n]
    # DP array where dp[c] is True if capacity c can be achieved
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in items:
        if vol > V:
            continue
        for cap in range(V, vol - 1, -1):
            if dp[cap - vol]:
                dp[cap] = True
    # Find the maximum achievable capacity not exceeding V
    max_sum = 0
    for cap in range(V, -1, -1):
        if dp[cap]:
            max_sum = cap
            break
    return V - max_sum

