def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0
    # Longest increasing subsequence ending at i
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1
    # Longest decreasing subsequence starting at i
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1
    # Longest bitonic subsequence
    max_len = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_len:
            max_len = bitonic_len
    return n - max_len

