def min_groups(w, n, prices):
    prices.sort()
    i, j = 0, n - 1
    pairs = 0
    while i < j:
        if prices[i] + prices[j] <= w:
            pairs += 1
            i += 1
            j -= 1
        else:
            j -= 1
    return n - pairs

